begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('40000000-0000-0000-0000-000000000001'),('40000000-0000-0000-0000-000000000002'),('40000000-0000-0000-0000-000000000003');
insert into deardaily_private.moderators values('40000000-0000-0000-0000-000000000003');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.public_profiles'::regclass),'profiles force RLS');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(public.my_public_profile(),null::jsonb,'no automatic public profile');
select lives_ok($$insert into public.public_profiles(username,display_name,bio) values('writer_a','Pseudonym A','Chosen bio')$$,'A creates hidden profile');
select is(public.my_public_profile()->>'visible','false','default profile invisible');
select throws_ok($$select user_id from public.public_profiles$$,'42501',null,'authenticated cannot read public ownership IDs');
select throws_ok($$insert into public.public_profiles(username,display_name) values('../bad','Bad')$$,'23514',null,'malformed username rejected');
select throws_ok($$update public.public_profiles set user_id='40000000-0000-0000-0000-000000000002'$$,'42501',null,'profile ownership immutable');
select throws_ok($$insert into public.public_profiles(user_id,username,display_name) values('40000000-0000-0000-0000-000000000002','spoof_user','Spoof')$$,'42501',null,'cannot set another profile owner');
select lives_ok($$insert into public.journal_entries(id,title,body) values('50000000-0000-0000-0000-000000000001','SECRET','PRIVATE WORDS')$$,'private source');
select throws_ok($$insert into public.public_stories(id,user_id,title,body,public_username) values('50000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','Public title','Public words','writer_a')$$,'42501',null,'hidden identity attribution denied');
select lives_ok($$insert into public.public_stories(id,user_id,title,body) values('50000000-0000-0000-0000-000000000001','40000000-0000-0000-0000-000000000001','Public title','Public words')$$,'anonymous pseudonym-free publication');
select is((select public_username from public.public_stories),null::text,'no automatic author exposure');
select lives_ok($$update public.public_profiles set visible=true where username='writer_a'$$,'explicit profile opt in');
select is((select public_username from public.public_stories),null::text,'opt in does not attach existing stories');
select lives_ok($$update public.public_stories set public_username='writer_a',public_category='Growth',public_tags=array['chosen']$$,'explicit author and metadata');
select throws_ok($$update public.public_stories set public_tags=array[repeat('x',31)]$$,'23514',null,'public tag length enforced');
select throws_ok($$update public.public_stories set public_category='private mood'$$,'23514',null,'invalid public category denied');
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is(public.my_public_profile(),null::jsonb,'B cannot get A owner profile');
select throws_ok($$insert into public.public_profiles(username,display_name) values('writer_a','B')$$,'23505',null,'unique username');
select lives_ok($$insert into public.public_profiles(username,display_name) values('writer_b','B')$$,'B has own identity');
select lives_ok($$update public.public_profiles set bio='ATTACK' where username='writer_a'$$,'B update matches no A row');
select lives_ok($$delete from public.public_profiles where username='writer_a'$$,'B cannot remove A profile');
select throws_ok($$insert into deardaily_private.moderators values(auth.uid())$$,'42501',null,'cannot self elevate');
select throws_ok($$select * from deardaily_private.reports$$,'42501',null,'reports private');
select throws_ok($$select * from deardaily_private.moderation_audit$$,'42501',null,'audit private');
select throws_ok($$select public.validate_public_attribution()$$,'42501',null,'trigger helper not callable');
select throws_ok($$select public.moderation_queue()$$,'42501',null,'ordinary user denied moderation queue');
select throws_ok($$select public.moderate_report(gen_random_uuid(),'remove','attack')$$,'42501',null,'ordinary user denied moderation decision');
select lives_ok($$select public.submit_story_report('50000000-0000-0000-0000-000000000001','spam','Synthetic report')$$,'B submits report');
select throws_ok($$select public.submit_story_report('50000000-0000-0000-0000-000000000001','spam','Duplicate')$$,'23505',null,'server blocks duplicate report');
select throws_ok($$select public.submit_story_report(gen_random_uuid(),'spam','Bad target')$$,'22023',null,'nonexistent target rejected');
select lives_ok($$select public.request_account_deletion()$$,'private deletion request');
select lives_ok($$select public.request_account_deletion()$$,'deletion request idempotent');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select is((select count(username)::int from public.public_profiles),1,'anon sees only opted in profile');
select is((select bio from public.public_profiles),'Chosen bio','B attack did not change A biography');
select throws_ok($$select user_id from public.public_profiles$$,'42501',null,'anon cannot read profile owner');
select throws_ok($$select * from public.public_profiles$$,'42501',null,'profile wildcard blocked');
select throws_ok($$select * from public.journal_entries$$,'42501',null,'private entries remain blocked');
select throws_ok($$select user_id from public.public_stories$$,'42501',null,'story owner remains hidden');
select is((select public_username from public.public_stories),'writer_a','only opted in public byline visible');
select is((select public_tags from public.public_stories),array['chosen'],'only chosen tags visible');
select throws_ok($$select public.submit_story_report('50000000-0000-0000-0000-000000000001','spam','Anonymous spam')$$,'42501',null,'anonymous report abuse blocked');
select throws_ok($$select public.my_public_profile()$$,'42501',null,'anonymous owner accessor denied');
select throws_ok($$select public.request_account_deletion()$$,'42501',null,'anonymous deletion denied');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select lives_ok($$update public.public_profiles set visible=false$$,'A opts out');
select is((select public_username from public.public_stories),null::text,'optout detaches all story attribution');
select lives_ok($$update public.public_profiles set visible=true$$,'A opts back in');
select is((select public_username from public.public_stories),null::text,'opt back in does not silently relink');
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
update public.public_profiles set visible=true;
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select throws_ok($$update public.public_stories set public_username='writer_b'$$,'42501',null,'A cannot impersonate B');
-- Create six more synthetic stories as A; B may report five total within 24h.
insert into public.journal_entries(id,title,body) select ('50000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Synthetic','Only fixture' from generate_series(2,7)n;
insert into public.public_stories(id,user_id,title,body) select id,auth.uid(),title,body from public.journal_entries where id<>'50000000-0000-0000-0000-000000000001';
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.submit_story_report('50000000-0000-0000-0000-000000000002','invalid','')$$,'23514',null,'bad report reason rejected');
select throws_ok($$select public.submit_story_report('50000000-0000-0000-0000-000000000002','other',repeat('x',1001))$$,'23514',null,'report explanation bounded');
select lives_ok($$select public.submit_story_report(('50000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'spam','Synthetic') from generate_series(2,5)n$$,'four more reports accepted');
select throws_ok($$select public.submit_story_report('50000000-0000-0000-0000-000000000006','spam','Sixth')$$,'54000',null,'server enforces daily limit');
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select is(jsonb_array_length(public.moderation_queue()),5,'authorized moderator gets queue');
select ok(not ((public.moderation_queue()->0) ? 'reporter_id'),'queue omits reporter identity');
select throws_ok($$select public.moderate_report((public.moderation_queue()->0->>'id')::uuid,'invalid','note')$$,'22023',null,'invalid decision rejected');
select lives_ok($$select public.moderate_report((select r->>'id' from jsonb_array_elements(public.moderation_queue())r where r->>'story_id'='50000000-0000-0000-0000-000000000001')::uuid,'remove','Synthetic removal')$$,'moderator removes publication');
select is((select count(id)::int from public.public_stories where id='50000000-0000-0000-0000-000000000001'),0,'removed story not public');
select lives_ok($$select public.moderate_report((public.moderation_queue()->0->>'id')::uuid,'dismiss','Synthetic dismissal')$$,'moderator dismisses');
select is(jsonb_array_length(public.moderation_queue()),3,'resolved reports leave queue');
select set_config('request.jwt.claims','{"sub":"40000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is((select body from public.journal_entries where id='50000000-0000-0000-0000-000000000001'),'PRIVATE WORDS','moderation preserves private source');
select throws_ok($$insert into public.public_stories(id,user_id,title,body) values('50000000-0000-0000-0000-000000000001',auth.uid(),'Retry','Retry')$$,'42501',null,'moderated entry cannot be republished');
select lives_ok($$delete from public.public_stories where id='50000000-0000-0000-0000-000000000002'$$,'owner unpublishes');
set local role anon;
select set_config('request.jwt.claims','{"role":"anon"}',true);
select is((select count(id)::int from public.public_stories where id='50000000-0000-0000-0000-000000000002'),0,'unpublished story revoked');
reset role;
select is((select count(*)::int from deardaily_private.moderation_audit),2,'two audited decisions');
select is((select count(*)::int from deardaily_private.deletion_requests),1,'one deletion request');
select * from finish();
rollback;
